function changes(base, side, who) {
  const n = base.length
  const m = side.length
  const L = Array.from({ length: n + 1 }, () => new Int32Array(m + 1))
  for (let i = n - 1; i >= 0; i--) {
    for (let j = m - 1; j >= 0; j--) {
      L[i][j] = base[i] === side[j] ? L[i + 1][j + 1] + 1 : Math.max(L[i + 1][j], L[i][j + 1])
    }
  }
  const out = []
  let i = 0
  let j = 0
  let bs = 0
  let ss = 0
  const flush = () => {
    if (i > bs || j > ss) out.push({ bs, be: i, ss, se: j, who })
  }
  while (i < n || j < m) {
    if (i < n && j < m && base[i] === side[j]) {
      flush()
      i++
      j++
      bs = i
      ss = j
    } else if (i < n && (j >= m || L[i + 1][j] >= L[i][j + 1])) {
      i++
    } else {
      j++
    }
  }
  flush()
  return out
}

const same = (a, b) => a.length === b.length && a.every((x, k) => x === b[k])

export function merge(mode, mine, base, theirs) {
  const all = [...changes(base, mine, 0), ...changes(base, theirs, 1)]
  all.sort((a, b) => a.bs - b.bs || a.who - b.who)
  const out = []
  let conflict = false
  const regions = mode === 'regions'
  let pos = 0
  const stable = end => {
    if (end > pos) {
      if (regions) out.push(`stable ${end - pos}`)
      else out.push(...base.slice(pos, end))
    }
  }
  let k = 0
  while (k < all.length) {
    const group = [all[k++]]
    const rs = group[0].bs
    let re = group[0].be
    while (k < all.length && all[k].bs <= re) {
      re = Math.max(re, all[k].be)
      group.push(all[k++])
    }
    stable(rs)
    pos = re
    const baseLines = base.slice(rs, re)
    const rep = (who, lines) => {
      const cs = group.filter(c => c.who === who)
      if (!cs.length) return baseLines
      const s = Math.min(...cs.map(c => c.bs))
      const e = Math.max(...cs.map(c => c.be))
      const ss = Math.min(...cs.map(c => c.ss)) - (s - rs)
      const se = Math.max(...cs.map(c => c.se)) + (re - e)
      return lines.slice(ss, se)
    }
    const m = rep(0, mine)
    const t = rep(1, theirs)
    let label
    let res
    if (group.length === 1) {
      label = group[0].who === 0 ? 'mine' : 'theirs'
      res = group[0].who === 0 ? m : t
    } else if (same(m, t)) {
      label = 'both'
      res = m
    } else if (same(m, baseLines)) {
      label = 'theirs'
      res = t
    } else if (same(t, baseLines)) {
      label = 'mine'
      res = m
    }
    if (res) {
      if (regions) out.push(`${label} ${res.length}`)
      else out.push(...res)
    } else {
      conflict = true
      if (regions) {
        out.push(`conflict mine=${m.length} base=${baseLines.length} theirs=${t.length}`)
      } else {
        out.push('<<<<<<< mine', ...m)
        if (mode === 'merge') out.push('||||||| base', ...baseLines)
        out.push('=======', ...t, '>>>>>>> theirs')
      }
    }
  }
  stable(base.length)
  return { out, conflict }
}
"}

